// 1. Get the results array
const jobs = $input.first().json.results || [];

return jobs
  .map(job => ({
    title: job.name || "Unknown Title",
    company: job.company ? job.company.name : "Unknown Company",
    // TRUNCATE the massive HTML description to save AI tokens later
    description: job.contents ? job.contents.substring(0, 3000) : "",
    url: job.refs ? job.refs.landing_page : "",
    source: "TheMuse",
    location: (job.locations && job.locations.length > 0) 
      ? job.locations.map(l => l.name).join(', ') 
      : "Not specified",
    work_mode: (job.locations && job.locations.some(l => l.name.toLowerCase().includes("remote"))) 
      ? "Remote" 
      : "On-site",
    posted_at: job.publication_date || ""
  }))
  .filter(job => {
    const loc = job.location.toLowerCase();
    // Broaden the filter so we don't drop everything
    return loc.includes("philippines") || 
           loc.includes("worldwide") || 
           loc.includes("asia") || 
           loc.includes("remote") || 
           loc.includes("anywhere") ||
           loc.includes("manila");
  });

// 1. Get the AI response
const response = $input.first().json;

if (response.error) {
  throw new Error("API Error: " + JSON.stringify(response.error));
}

// 2. Extract content (handle both Gemini and Ollama formats)
let content;
if (response.choices && response.choices[0]) {
  content = response.choices[0].message.content;
} else if (response.message && response.message.content) {
  content = response.message.content;
} else {
  throw new Error("Unknown response format.");
}

// 3. Clean up markdown
content = content.replace(/```json/g, '').replace(/```/g, '').trim();

// 4. Try to extract valid JSON (fallback to regex if parse fails)
let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  const matchRegex = /\{\s*"index"\s*:\s*(\d+)\s*,\s*"score"\s*:\s*(\d+)\s*,\s*"reason"\s*:\s*"([^"]*)"\s*\}/g;
  const matches = [];
  let m;
  while ((m = matchRegex.exec(content)) !== null) {
    matches.push({
      index: parseInt(m[1]),
      score: parseInt(m[2]),
      reason: m[3]
    });
  }
  if (matches.length === 0) {
    throw new Error("Could not parse JSON. Raw content: " + content.substring(0, 500));
  }
  parsed = { matches: matches };
}

const scores = parsed.matches || [];

// 5. Get the original batch of jobs
const jobs = $(' a "Code" Node before the HTTP Request').item.json.original_jobs;

// 6. Map scores back to jobs
return jobs.map((job, i) => ({
  ...job,
  match_score: scores[i]?.score || 0,
  ai_reason: scores[i]?.reason || "No reason provided."
}));

// 1. Grab the batch of items from the Loop node
const jobs = $input.all().map(item => item.json);

// 2. Grab the resume text
const resumeText = $('Edit Fields').first().json.resume_text;

// 3. Build the jobs string
const jobsString = jobs.map((j, i) => `
---
Index: ${i}
Title: ${j.title}
Company: ${j.company}
Location: ${j.location}
Description: ${j.description ? j.description.substring(0, 1000) : ''}
`).join('\n');

// 4. Build the prompt
const prompt = `CANDIDATE LOCATION: Philippines\nRESUME:\n${resumeText}\n\nJOBS:\n${jobsString}\n\nReturn ONLY a JSON object with a "matches" array, one entry per job in the same order as listed above: { "matches": [{ "index": 0, "score": 85, "reason": "..." }] }`;

// 5. Build the Gemini request body
const body = {
  model: "gemini-1.5-flash",
  messages: [{ role: "user", content: prompt }],
  response_format: { type: "json_object" }
};

// 6. Build the Ollama (Local AI) request body - NATIVE API
const ollama_body = {
  model: "llama3.1:8b",  // 🚨 Changed from qwen3:4b
  messages: [
    { role: "system", content: "You output ONLY valid JSON. No explanations, no markdown." },
    { role: "user", content: prompt }
  ],
  stream: false,
  format: "json",        // Forces valid JSON output
  options: {
    temperature: 0.1,
    num_ctx: 8192
  }
};

// 7. Return everything needed
return [{ json: { 
  body: body, 
  ollama_body: JSON.stringify(ollama_body), // Serialized safely!
  original_jobs: jobs 
} }];

// 1. Get the aggregated matches
const matches = $input.first().json.matches || [];

if (matches.length === 0) {
  return [{ json: { html: "<p>No strong matches found today. Check back tomorrow!</p>" } }];
}

let html = `<h2>🎯 Your Job Matches for ${new Date().toDateString()}</h2>`;
html += `<p>Found <strong>${matches.length}</strong> strong matches today.</p>`;

// 2. Sort by match_score descending
matches.sort((a, b) => b.match_score - a.match_score).forEach((job, i) => {
  html += `
    <div style="border:1px solid #ddd; padding:15px; margin:10px 0; border-radius:8px; font-family: Arial, sans-serif;">
      <h3 style="margin-top:0;">${i+1}. ${job.title} — <span style="color: #4CAF50;">${job.match_score}/100</span></h3>
      <p><strong>Company:</strong> ${job.company}</p>
      <p><strong>Location:</strong> ${job.location} (${job.work_mode})</p>
      <p><strong>Why it's a match:</strong> ${job.ai_reason}</p>
      <p><a href="${job.url}" style="display:inline-block; padding:10px 15px; background-color:#007BFF; color:#fff; text-decoration:none; border-radius:5px;">Apply Now →</a></p>
    </div>`;
});

html += `<p style="color:#888; font-size:12px;">Sent by your n8n Job Bot</p>`;
return [{ json: { html } }];

// The Aggregate node wraps everything into a single item with a "matches" array
const matches = $input.first().json.matches || [];

// Filter by score, then wrap back into a "matches" object
const filtered = matches.filter(job => job.match_score >= 80);

return [{ json: { matches: filtered } }];

const stdout = $input.first().json.stdout || "";
const raw = typeof stdout === 'string' ? stdout : JSON.stringify(stdout);

let jobs = [];
try {
  jobs = JSON.parse(raw.trim());
} catch (e) {
  throw new Error("Failed to parse: " + e.message);
}

return jobs.map(job => ({ json: job }));

// JobStreet v5 API returns results in data[0].results
const items = $input.first().json.data?.[0]?.results || [];

return items.map(item => {
  const job = item.job || item;
  const advertiser = item.advertiser || job.advertiser || {};

  // Build the full job URL from the job ID
  const jobId = job.id || item.id || "";
  const url = jobId ? `https://ph.jobstreet.com/job/${jobId}` : "";

  // Extract location from the nested structure
  const location = job.location || advertiser.location || "Philippines";

  // Detect work mode from work arrangement
  const arrangement = (job.workArrangement || []).map(w => w.label || w).join(", ").toLowerCase();
  let workMode = "On-site";
  if (arrangement.includes("remote")) workMode = "Remote";
  else if (arrangement.includes("hybrid")) workMode = "Hybrid";

  return {
    title: job.title || "Unknown",
    company: advertiser.name || job.companyName || "Unknown",
    description: job.teaser || job.description || "",
    url: url,
    source: "JobStreet",
    location: location,
    work_mode: workMode,
    posted_at: job.listedAt || job.listingDate || ""
  };
});
